function solution(nums, target) {
  const sums = new Map([[0, -1]]);
  let currentSum = 0;
  for (let end = 0; end < nums.length; end++) {
    currentSum += nums[end];
    const targetSum = currentSum - target;
    if (sums.has(targetSum)) {
      const start = sums.get(targetSum) + 1;
      return `(${start}, ${end})`
    }
    if (!sums.has(currentSum)) {
      sums.set(currentSum, end);
    }
  }
  return null;
}

function solution(str) {
    let t = 0, n = 0, b = 1;
    for (let char of str) {
        if (char.trim() === "") continue;
        if (char === "*" || char === "+") {
            b *= n;
            if (char === "+") {
                t += b;
                b = 1;
            }
            n = 0;
        } else {
            n = n * 10 + (char - '0');
        }
    }
    b *= n;
    t += b;
    return t;
}

function solution(nums, target) {
  let left = 0;
  let right = nums.length - 1;

  while (left <= right) {
    const mid = Math.floor((left + right) / 2);
    const num = nums[mid];

    if (num === target) return mid;
    num < target ? (left = mid + 1) : (right = mid - 1);
  }

  return left;
}

function solution(array) {

  const n = array.length;

    for (let i = 0; i < n; i++) {
        while (array[i] > 0 && array[i] <= n && array[array[i] - 1] !== array[i]) {
            const correctIndex = array[i] - 1;
            const temp = array[i];
            array[i] = array[correctIndex];
            array[correctIndex] = temp;
        }
    }

