}

function solution(nums) {
  if (nums.length === 0) return "";
  if (nums.length === 1) return `${nums[0]}`;
  const s = new Set(nums);
  let ranges = [];
  s.forEach((n) => {
    if (s.has(n - 1)) return;
    const l = n;
    let r = n;

    while (s.has(r + 1)) {
      r += 1;
    }

    ranges.push({ l, r })
  })

  ranges.sort((a, b) => a.l - b.l);
  const rangesConvert = ranges.map(({ l, r }) => {
    return l === r ? `${l}` : `${l}-${r}`;
  }).join(',')

  return rangesConvert;
}

function solution(str) {
  let minRange = Infinity;
  let lastX = -1;
  let lastY = -1;
  for (let i = 0; i < str.length; i++) {
    const char = str[i];
    if (char !== "X" && char !== "Y") continue;
    if (char === "X") {
      lastX = i
      if (lastY !== -1) minRange = Math.min(minRange, lastX - lastY);
    }
    else {
      lastY = i
      if (lastX !== -1) minRange = Math.min(minRange, lastY - lastX);
    };
  }
  return minRange === Infinity ? 0 : minRange;
}

function solution(strs) {
