        return "";
    for (let i = 0; strs[0].length; i++) {
        const char = strs[0][i];
        for (let j = 1; j < strs.length; j++) {
            const compChar = strs[j][i];
            if (char !== compChar) {
                return strs[0].substring(0, i);
            }
        }
    }
